const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Atacama Desert region
  const atacama = ee.Geometry.Rectangle([-70.5, -25.5, -68.0, -22.5]);

  // 2. Define time period
  const startDate = '2025-06-01';
  const endDate = '2025-07-31';

  // 3. Load Sentinel-2 data
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(atacama)
    .filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // 4. If no Sentinel-2, try Landsat 9
  if (collectionSize === 0) {
    console.log('Trying Landsat 9...');
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(atacama)
      .filterDate(startDate, endDate);

    const l9Size = collection.size().getInfo();
    console.log(`Landsat 9 images found: ${l9Size}`);

    if (l9Size === 0) {
      console.log('No images available for June-July 2025.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Process collection for snow detection
  function addNDSI(image) {
    let ndsi;
    if (image.bandNames().contains('B3').getInfo()) {
      // Sentinel-2: Green=B3, SWIR=B11
      ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    } else {
      // Landsat: Green=SR_B3, SWIR=SR_B6
      ndsi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('NDSI');
    }
    return image.addBands(ndsi);
  }

  function maskClouds(image) {
    if (image.bandNames().contains('QA60').getInfo()) {
      // Sentinel-2 cloud masking
      const qa = image.select('QA60');
      const cloudMask = qa.bitwiseAnd(1024).eq(0).and(qa.bitwiseAnd(2048).eq(0));
      return image.updateMask(cloudMask);
    } else {
      // Landsat cloud masking
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(8).eq(0).and(qa.bitwiseAnd(16).eq(0));
      return image.updateMask(cloudMask);
    }
  }

  const processedCollection = collection.map(maskClouds).map(addNDSI);

  // 6. Create composite and check for snow
  const ndsiComposite = processedCollection.select('NDSI').max();

  // 7. Count valid pixels
  const pixelCount = ndsiComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: atacama,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  console.log(`Valid pixels after cloud masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate snow statistics
  const snowThreshold = 0.4;
  const snowMask = ndsiComposite.gt(snowThreshold);

  const snowPixels = snowMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: atacama,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  const maxNDSI = ndsiComposite.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: atacama,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  console.log(`Max NDSI value: ${maxNDSI !== null ? maxNDSI.toFixed(3) : 'null'}`);
  console.log(`Snow pixels (NDSI > 0.4): ${snowPixels !== null ? Math.round(snowPixels) : 'null'}`);

  // 9. Validate and determine answer
  if (maxNDSI === null || snowPixels === null) {
    console.log('Calculation failed to return valid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (snowPixels > 0) {
    console.log('Snow detected in Atacama Desert during June-July 2025.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No snow detected in Atacama Desert during June-July 2025.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
